-- Migration 033: app accounts, product catalog, API token storage and orders.
-- No historical customer/shop ownership is inferred here. A populated deployment must
-- complete a separate reviewed mapping/recovery plan before customer ordering is enabled.
SET @lpg033_sql = IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='locations' AND INDEX_NAME='uq_locations_id_business')=0,'ALTER TABLE locations ADD UNIQUE KEY uq_locations_id_business(id,business_id)','SELECT 1');
PREPARE lpg033_stmt FROM @lpg033_sql; EXECUTE lpg033_stmt; DEALLOCATE PREPARE lpg033_stmt;
SET @lpg033_sql = IF((SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='customers' AND INDEX_NAME='uq_customers_id_location')=0,'ALTER TABLE customers ADD UNIQUE KEY uq_customers_id_location(id,location_id)','SELECT 1');
PREPARE lpg033_stmt FROM @lpg033_sql; EXECUTE lpg033_stmt; DEALLOCATE PREPARE lpg033_stmt;
CREATE TABLE IF NOT EXISTS business_catalog_products(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id BIGINT UNSIGNED NOT NULL,cylinder_type_id BIGINT UNSIGNED NOT NULL,sale_mode ENUM('sell_gas_only','sell_filled','sell_empty') NOT NULL,display_name VARCHAR(150) NOT NULL,description VARCHAR(500),quantity_unit ENUM('kg','cylinder') NOT NULL,min_quantity DECIMAL(14,3) NOT NULL DEFAULT 1,quantity_step DECIMAL(14,3) NOT NULL DEFAULT 1,is_active BOOLEAN NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0,created_by BIGINT UNSIGNED,updated_by BIGINT UNSIGNED,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_business_catalog_product(business_id,cylinder_type_id,sale_mode),UNIQUE KEY uq_catalog_product_business(id,business_id),KEY idx_business_catalog_active(business_id,is_active,sort_order),CONSTRAINT fk_catalog_business FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE CASCADE,CONSTRAINT fk_catalog_cylinder_type FOREIGN KEY(cylinder_type_id) REFERENCES cylinder_types(id) ON DELETE RESTRICT,CONSTRAINT fk_catalog_created_by FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE SET NULL,CONSTRAINT fk_catalog_updated_by FOREIGN KEY(updated_by) REFERENCES users(id) ON DELETE SET NULL,CHECK(min_quantity>0 AND quantity_step>0),CHECK((sale_mode='sell_gas_only' AND quantity_unit='kg') OR (sale_mode IN('sell_filled','sell_empty') AND quantity_unit='cylinder')))ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS shop_product_availability(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id BIGINT UNSIGNED NOT NULL,location_id BIGINT UNSIGNED NOT NULL,business_catalog_product_id BIGINT UNSIGNED NOT NULL,is_active BOOLEAN NOT NULL DEFAULT 1,updated_by BIGINT UNSIGNED,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_shop_catalog_product(location_id,business_catalog_product_id),KEY idx_shop_product_active(location_id,is_active),CONSTRAINT fk_shop_product_location_business FOREIGN KEY(location_id,business_id) REFERENCES locations(id,business_id) ON DELETE CASCADE,CONSTRAINT fk_shop_product_catalog_business FOREIGN KEY(business_catalog_product_id,business_id) REFERENCES business_catalog_products(id,business_id) ON DELETE CASCADE,CONSTRAINT fk_shop_product_updated_by FOREIGN KEY(updated_by) REFERENCES users(id) ON DELETE SET NULL)ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS customer_app_accounts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT UNSIGNED NOT NULL,username VARCHAR(80) NOT NULL,password_hash VARCHAR(255) NOT NULL,status ENUM('approved','disabled') NOT NULL DEFAULT 'approved',approved_by BIGINT UNSIGNED,approved_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,last_login_at DATETIME,password_changed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_customer_account_customer(customer_id),UNIQUE KEY uq_customer_account_username(username),UNIQUE KEY uq_customer_account_pair(id,customer_id),CONSTRAINT fk_customer_account_customer FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE RESTRICT,CONSTRAINT fk_customer_account_approver FOREIGN KEY(approved_by) REFERENCES users(id) ON DELETE SET NULL)ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS customer_signup_requests(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id BIGINT UNSIGNED NOT NULL,requested_location_id BIGINT UNSIGNED NOT NULL,username VARCHAR(80) NOT NULL,password_hash VARCHAR(255),customer_name VARCHAR(150) NOT NULL,phone VARCHAR(30),city VARCHAR(80),address VARCHAR(255),vehicle_no VARCHAR(40),status ENUM('pending_approval','approved','rejected') NOT NULL DEFAULT 'pending_approval',linked_customer_id BIGINT UNSIGNED,reviewed_by BIGINT UNSIGNED,reviewed_at DATETIME,rejection_reason VARCHAR(500),created_ip VARCHAR(45),user_agent VARCHAR(500),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_signup_queue(requested_location_id,status,created_at),KEY idx_signup_username(username,status),KEY idx_signup_business(business_id,status),CONSTRAINT fk_signup_location_business FOREIGN KEY(requested_location_id,business_id) REFERENCES locations(id,business_id) ON DELETE RESTRICT,CONSTRAINT fk_signup_linked_customer_location FOREIGN KEY(linked_customer_id,requested_location_id) REFERENCES customers(id,location_id) ON DELETE RESTRICT,CONSTRAINT fk_signup_reviewer FOREIGN KEY(reviewed_by) REFERENCES users(id) ON DELETE SET NULL,CHECK((status='pending_approval' AND reviewed_at IS NULL) OR (status<>'pending_approval' AND reviewed_at IS NOT NULL)))ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS api_sessions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,audience ENUM('customer','staff') NOT NULL,customer_app_account_id BIGINT UNSIGNED,user_id BIGINT UNSIGNED,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,last_activity_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at DATETIME NOT NULL,absolute_expires_at DATETIME NOT NULL,revoked_at DATETIME,created_ip VARCHAR(45),user_agent VARCHAR(500),KEY idx_api_session_customer(customer_app_account_id,revoked_at),KEY idx_api_session_staff(user_id,revoked_at),KEY idx_api_session_active(audience,revoked_at,expires_at),CONSTRAINT fk_api_session_customer FOREIGN KEY(customer_app_account_id) REFERENCES customer_app_accounts(id) ON DELETE CASCADE,CONSTRAINT fk_api_session_staff FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CHECK((audience='customer' AND customer_app_account_id IS NOT NULL AND user_id IS NULL) OR (audience='staff' AND user_id IS NOT NULL AND customer_app_account_id IS NULL)),CHECK(expires_at<=absolute_expires_at))ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS api_access_tokens(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,api_session_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,expires_at DATETIME NOT NULL,revoked_at DATETIME,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_api_access_token_hash(token_hash),KEY idx_api_access_session(api_session_id,revoked_at,expires_at),CONSTRAINT fk_api_access_session FOREIGN KEY(api_session_id) REFERENCES api_sessions(id) ON DELETE CASCADE)ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS api_refresh_tokens(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,api_session_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,expires_at DATETIME NOT NULL,consumed_at DATETIME,revoked_at DATETIME,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_api_refresh_token_hash(token_hash),KEY idx_api_refresh_session(api_session_id,consumed_at,revoked_at),CONSTRAINT fk_api_refresh_session FOREIGN KEY(api_session_id) REFERENCES api_sessions(id) ON DELETE CASCADE)ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS customer_orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,business_id BIGINT UNSIGNED NOT NULL,location_id BIGINT UNSIGNED NOT NULL,customer_id BIGINT UNSIGNED NOT NULL,customer_app_account_id BIGINT UNSIGNED NOT NULL,order_no VARCHAR(40) NOT NULL,idempotency_key VARCHAR(100) NOT NULL,status ENUM('pending','accepted','rejected','preparing','ready','out_for_delivery','completed','cancelled','unable_to_fulfil') NOT NULL DEFAULT 'pending',fulfilment_method ENUM('delivery','collection') NOT NULL,customer_name_snapshot VARCHAR(150) NOT NULL,customer_phone_snapshot VARCHAR(30),delivery_address_snapshot VARCHAR(500),delivery_city_snapshot VARCHAR(80),delivery_fee DECIMAL(14,2) NOT NULL DEFAULT 0,subtotal DECIMAL(14,2) NOT NULL,discount_amount DECIMAL(14,2) NOT NULL DEFAULT 0,total_amount DECIMAL(14,2) NOT NULL,customer_notes VARCHAR(1000),staff_notes VARCHAR(1000),accepted_by BIGINT UNSIGNED,accepted_at DATETIME,rejected_by BIGINT UNSIGNED,rejected_at DATETIME,rejection_reason VARCHAR(500),completed_by BIGINT UNSIGNED,completed_at DATETIME,cancelled_by BIGINT UNSIGNED,cancelled_at DATETIME,cancellation_reason VARCHAR(500),pos_sale_id BIGINT UNSIGNED,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_customer_order_no(business_id,order_no),UNIQUE KEY uq_customer_order_idempotency(customer_app_account_id,idempotency_key),UNIQUE KEY uq_customer_order_id_business(id,business_id),UNIQUE KEY uq_customer_order_pos_sale(pos_sale_id),KEY idx_customer_orders_shop_queue(location_id,status,created_at),KEY idx_customer_orders_customer(customer_id,created_at),KEY idx_customer_orders_business(business_id,status,created_at),CONSTRAINT fk_customer_order_business FOREIGN KEY(business_id) REFERENCES businesses(id) ON DELETE RESTRICT,CONSTRAINT fk_customer_order_location_business FOREIGN KEY(location_id,business_id) REFERENCES locations(id,business_id) ON DELETE RESTRICT,CONSTRAINT fk_customer_order_customer_location FOREIGN KEY(customer_id,location_id) REFERENCES customers(id,location_id) ON DELETE RESTRICT,CONSTRAINT fk_customer_order_account_customer FOREIGN KEY(customer_app_account_id,customer_id) REFERENCES customer_app_accounts(id,customer_id) ON DELETE RESTRICT,CONSTRAINT fk_customer_order_pos_sale FOREIGN KEY(pos_sale_id) REFERENCES sales(id) ON DELETE RESTRICT,CONSTRAINT fk_customer_order_accepted_by FOREIGN KEY(accepted_by) REFERENCES users(id) ON DELETE SET NULL,CONSTRAINT fk_customer_order_rejected_by FOREIGN KEY(rejected_by) REFERENCES users(id) ON DELETE SET NULL,CONSTRAINT fk_customer_order_completed_by FOREIGN KEY(completed_by) REFERENCES users(id) ON DELETE SET NULL,CONSTRAINT fk_customer_order_cancelled_by FOREIGN KEY(cancelled_by) REFERENCES users(id) ON DELETE SET NULL,CHECK(subtotal>=0 AND discount_amount>=0 AND delivery_fee>=0 AND total_amount>=0),CHECK((fulfilment_method='delivery' AND delivery_address_snapshot IS NOT NULL) OR fulfilment_method='collection'))ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS customer_order_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,business_id BIGINT UNSIGNED NOT NULL,line_no SMALLINT UNSIGNED NOT NULL,business_catalog_product_id BIGINT UNSIGNED NOT NULL,cylinder_type_id BIGINT UNSIGNED NOT NULL,sale_mode ENUM('sell_gas_only','sell_filled','sell_empty') NOT NULL,product_name_snapshot VARCHAR(150) NOT NULL,quantity_unit ENUM('kg','cylinder') NOT NULL,quantity DECIMAL(14,3) NOT NULL,estimated_gas_kg DECIMAL(14,3) NOT NULL DEFAULT 0,gas_rate_snapshot DECIMAL(14,4) NOT NULL DEFAULT 0,cylinder_rate_snapshot DECIMAL(14,4) NOT NULL DEFAULT 0,line_total DECIMAL(14,2) NOT NULL,notes VARCHAR(500),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_customer_order_line(order_id,line_no),KEY idx_customer_order_item_catalog(business_id,business_catalog_product_id),CONSTRAINT fk_customer_order_item_order_business FOREIGN KEY(order_id,business_id) REFERENCES customer_orders(id,business_id) ON DELETE RESTRICT,CONSTRAINT fk_customer_order_item_catalog_business FOREIGN KEY(business_catalog_product_id,business_id) REFERENCES business_catalog_products(id,business_id) ON DELETE RESTRICT,CONSTRAINT fk_customer_order_item_cylinder FOREIGN KEY(cylinder_type_id) REFERENCES cylinder_types(id) ON DELETE RESTRICT,CHECK(quantity>0 AND estimated_gas_kg>=0 AND line_total>=0),CHECK((sale_mode='sell_gas_only' AND quantity_unit='kg') OR (sale_mode IN('sell_filled','sell_empty') AND quantity_unit='cylinder')))ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS customer_order_status_history(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,business_id BIGINT UNSIGNED NOT NULL,from_status ENUM('pending','accepted','rejected','preparing','ready','out_for_delivery','completed','cancelled','unable_to_fulfil') NULL,to_status ENUM('pending','accepted','rejected','preparing','ready','out_for_delivery','completed','cancelled','unable_to_fulfil') NOT NULL,actor_type ENUM('customer','staff','system') NOT NULL,customer_app_account_id BIGINT UNSIGNED,user_id BIGINT UNSIGNED,reason VARCHAR(500),request_id VARCHAR(100),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_order_history(order_id,created_at),CONSTRAINT fk_customer_order_history_order FOREIGN KEY(order_id,business_id) REFERENCES customer_orders(id,business_id) ON DELETE RESTRICT,CONSTRAINT fk_customer_order_history_account FOREIGN KEY(customer_app_account_id) REFERENCES customer_app_accounts(id) ON DELETE RESTRICT,CONSTRAINT fk_customer_order_history_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,CHECK((actor_type='customer' AND customer_app_account_id IS NOT NULL AND user_id IS NULL) OR (actor_type='staff' AND user_id IS NOT NULL AND customer_app_account_id IS NULL) OR actor_type='system'))ENGINE=InnoDB;
